'use strict';
// Reads the saved pipeline files from disk, re-verifies the whole chain,
// and only then writes answer.json with numeric keys taken from those files.
const fs = require('fs');

function readNumber(file) {
  if (!fs.existsSync(file)) throw new Error(file + ' missing; cannot verify');
  const raw = fs.readFileSync(file, 'utf8').trim();
  const n = Number(raw);
  if (raw === '' || !Number.isFinite(n)) throw new Error(file + ' is not numeric: ' + JSON.stringify(raw));
  return n;
}

const seed = readNumber('seed.txt');
const stage1 = readNumber('stage1.txt');
const stage2 = readNumber('stage2.txt');
const stage3 = readNumber('stage3.txt');

const checks = [
  ['stage1 = seed + 2', stage1 === seed + 2, seed + 2, stage1],
  ['stage2 = stage1^2', stage2 === stage1 * stage1, stage1 * stage1, stage2],
  ['stage3 = stage2 - 4', stage3 === stage2 - 4, stage2 - 4, stage3],
];

let ok = true;
for (const [name, pass, expected, actual] of checks) {
  console.log((pass ? 'PASS' : 'FAIL') + ' ' + name + ' (expected ' + expected + ', found ' + actual + ')');
  if (!pass) ok = false;
}
if (!ok) throw new Error('pipeline verification failed; answer.json not written');

fs.writeFileSync('answer.json', JSON.stringify({ stage1, stage2, stage3 }, null, 2) + '\n');
console.log('all stages verified; answer.json written');

